import hashlib,importlib,json,random,statistics,time
from pathlib import Path
import torch,triton
m=importlib.import_module("sglang.kernels.ops.moe.moe_fused_mul_sum")
def emit(**r): print(json.dumps(r),flush=True)
emit(kind="environment",gpu=torch.cuda.get_device_name(),torch=torch.__version__,triton=triton.__version__,source_sha256=hashlib.sha256(Path(m.__file__).read_bytes()).hexdigest())
flush=torch.empty(96<<20,device="cuda",dtype=torch.uint8)
for rows in (4096,4097,8192,16384):
 gen=torch.Generator(device="cuda").manual_seed(117928+rows)
 x=torch.randn(rows,9,4096,device="cuda",dtype=torch.bfloat16,generator=gen)
 w=torch.rand(rows,9,device="cuda",generator=gen);w/=w.sum(1,keepdim=True)
 y=torch.empty(rows,4096,device="cuda",dtype=x.dtype)
 def run(enabled):
  m._AX_SM80_MOE_REDUCE=enabled
  return m.moe_fused_mul_sum(x,w,outputs=y,routed_scaling_factor=2.5)
 run(False);ref=y.clone();run(True)
 assert torch.equal(y.view(torch.int16),ref.view(torch.int16))
 for _ in range(10):run(False);run(True)
 rng=random.Random(117928+rows)
 samples={False:[],True:[]}
 for _ in range(5):
  flags=[False,True];rng.shuffle(flags)
  for flag in flags:
   vals=[]
   for _ in range(7):
    flush.fill_(1)
    a,b=torch.cuda.Event(enable_timing=True),torch.cuda.Event(enable_timing=True)
    a.record();run(flag);b.record();b.synchronize();vals.append(a.elapsed_time(b))
   samples[flag].append(statistics.median(vals))
 graphs={}
 for flag in (False,True):
  graph=torch.cuda.CUDAGraph()
  with torch.cuda.graph(graph):
   for _ in range(8):run(flag)
  graphs[flag]=graph
 graph_samples={False:[],True:[]}
 for _ in range(15):
  flags=[False,True];rng.shuffle(flags)
  for flag in flags:
   a,b=torch.cuda.Event(enable_timing=True),torch.cuda.Event(enable_timing=True)
   a.record();graphs[flag].replay();b.record();b.synchronize()
   graph_samples[flag].append(a.elapsed_time(b)/8)
 host={False:[],True:[]}
 for _ in range(5):
  flags=[False,True];rng.shuffle(flags)
  for flag in flags:
   torch.cuda.synchronize();start=time.perf_counter()
   for _ in range(30):run(flag)
   host[flag].append((time.perf_counter()-start)*1e3/30)
   torch.cuda.synchronize()
 emit(kind="production_timing",rows=rows,exact=True,cold_medians_ms={str(k):statistics.median(v) for k,v in samples.items()},cold_rounds_ms=samples,graph_medians_ms={str(k):statistics.median(v) for k,v in graph_samples.items()},graph_samples_ms=graph_samples,host_enqueue_median_ms={str(k):statistics.median(v) for k,v in host.items()},host_enqueue_samples_ms=host)
 del graphs,graph,x,w,y,ref
emit(kind="complete")
